from decimal import Decimal

import pytest

from refproj.pricing import MAX_PRICE, format_price, parse_price

# --- format_price: the printed form ---------------------------------------------------------


def test_format_always_prints_two_decimals() -> None:
    assert format_price(Decimal("12.5")) == "12.50"


def test_format_groups_thousands_with_commas() -> None:
    assert format_price(Decimal("1234.5")) == "1,234.50"


def test_format_of_zero_keeps_the_leading_zero_and_both_decimals() -> None:
    assert format_price(Decimal("0")) == "0.00"


@pytest.mark.parametrize(
    ("price", "printed"),
    [
        (Decimal("0.05"), "0.05"),
        (Decimal("5"), "5.00"),
        (Decimal("999.99"), "999.99"),
        (Decimal("1000"), "1,000.00"),
        (Decimal("123456.78"), "123,456.78"),
        (Decimal("1000000"), "1,000,000.00"),
    ],
)
def test_format_puts_a_comma_before_every_group_of_three(price: Decimal, printed: str) -> None:
    assert format_price(price) == printed


def test_format_accepts_both_ends_of_the_range() -> None:
    assert format_price(Decimal("0.00")) == "0.00"
    assert format_price(Decimal("9999999.99")) == "9,999,999.99"
    assert format_price(MAX_PRICE) == "9,999,999.99"


@pytest.mark.parametrize(
    "price",
    [Decimal("10000000.00"), Decimal("12345678.90"), Decimal("Infinity")],
)
def test_format_rejects_a_price_above_the_range(price: Decimal) -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(price)


@pytest.mark.parametrize("price", [Decimal("-0.01"), Decimal("-12.50")])
def test_format_rejects_a_price_below_the_range(price: Decimal) -> None:
