def test_format_never_prints_a_minus_sign_for_negative_zero() -> None:
    # Either reading of the contract is accepted here (see the questions): "0.00" or an error.
    try:
        printed = format_price(Decimal("-0.00"))
    except ValueError as error:
        assert "not a price" in str(error)
    else:
        assert printed == "0.00"


